"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs } from "./rs";

export interface SwitchProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

const styles = stylex.create({
  track: {
    display: "inline-flex",
    boxSizing: "border-box",
    width: {
      default: 32,
      [mq.phone]: 64,
    },
    height: {
      default: 18,
      [mq.phone]: raster.hit,
    },
    minWidth: {
      default: null,
      [mq.phone]: 64,
    },
    minHeight: {
      default: null,
      [mq.phone]: raster.hit,
    },
    borderRadius: {
      default: 9,
      [mq.phone]: 0,
    },
    borderWidth: 1.5,
    borderStyle: "solid",
    borderColor: {
      default: raster.controlBorder,
      [mq.forcedColors]: "ButtonText",
    },
    position: "relative",
    flexShrink: 0,
    padding: 0,
    backgroundColor: "transparent",
    cursor: "pointer",
    transition: {
      default: `background-color ${raster.duration} ${raster.ease}, border-color ${raster.duration} ${raster.ease}`,
      [mq.reduce]: "none",
    },
    outlineWidth: {
      default: null,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: null,
      ":focus-visible": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible": raster.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": 2,
    },
    /* The visible track stays 32×18; the hit area grows to 24px tall. */
    "::before": {
      content: '""',
      position: "absolute",
      top: -3,
      bottom: -3,
      left: 0,
      right: 0,
    },
  },
  on: {
    backgroundColor: {
      default: raster.ink,
      [mq.forcedColors]: "Highlight",
    },
    borderColor: {
      default: raster.ink,
      [mq.forcedColors]: "Highlight",
    },
    forcedColorAdjust: "none",
  },
  thumb: {
    position: "absolute",
    top: {
      default: 1.5,
      [mq.phone]: 4,
    },
    left: {
      default: 1.5,
      [mq.phone]: 4,
    },
    width: {
      default: 12,
      [mq.phone]: 36,
    },
    height: {
      default: 12,
      [mq.phone]: 36,
    },
    borderRadius: {
      default: "50%",
      [mq.phone]: 0,
    },
    backgroundColor: {
      default: raster.gray,
      [mq.forcedColors]: "ButtonText",
    },
    forcedColorAdjust: "none",
    transition: {
      default: `transform ${raster.duration} ${raster.ease}`,
      [mq.reduce]: "none",
    },
  },
  thumbOn: {
    backgroundColor: {
      default: raster.paper,
      [mq.forcedColors]: "HighlightText",
    },
    transform: {
      default: "translateX(14px)",
      [mq.phone]: "translateX(20px)",
    },
  },
});

/** A button with role="switch". */
export const Switch = React.forwardRef<HTMLButtonElement, SwitchProps>(function Switch(
  { checked, defaultChecked, onCheckedChange, className, style, onClick, ...props },
  ref,
) {
  const [inner, setInner] = React.useState(defaultChecked ?? false);
  const isControlled = checked !== undefined;
  const on = isControlled ? checked : inner;
  const sx = rs(["rs-switch", on && "rs-switch-on", className], styles.track, on && styles.on);
  const knob = rs(["rs-switch-thumb", on && "rs-switch-thumb-on"], styles.thumb, on && styles.thumbOn);
  return (
    <button
      ref={ref}
      type="button"
      role="switch"
      aria-checked={on}
      className={sx.className}
      style={{ ...sx.style, ...style }}
      onClick={(e) => {
        if (!isControlled) setInner(!on);
        onCheckedChange?.(!on);
        onClick?.(e);
      }}
      {...props}
    >
      <i className={knob.className} style={knob.style} />
    </button>
  );
});

/* ── switch: generated from packages/react/src/components/switch.tsx ── */
.rs-switch{display:inline-flex;box-sizing:border-box;width:32px;height:18px;border-radius:9px;border-width:1.5px;border-style:solid;border-color:var(--control-border);position:relative;flex-shrink:0;padding:0;background-color:transparent;cursor:pointer;transition:background-color var(--duration) var(--ease), border-color var(--duration) var(--ease)}
.rs-switch:focus-visible{outline-width:2px;outline-style:solid;outline-color:var(--text);outline-offset:2px}
.rs-switch::before{content:"";position:absolute;top:-3px;bottom:-3px;left:0;right:0}
@media (max-width: 640px){.rs-switch{width:64px;height:var(--hit);min-width:64px;min-height:var(--hit);border-radius:0}}
@media (forced-colors: active){.rs-switch{border-color:ButtonText}}
@media (prefers-reduced-motion: reduce){.rs-switch{transition:none}}
.rs-switch-on{background-color:var(--text);border-color:var(--text);forced-color-adjust:none}
@media (forced-colors: active){.rs-switch-on{background-color:Highlight;border-color:Highlight}}
.rs-switch-thumb{position:absolute;top:1.5px;left:1.5px;width:12px;height:12px;border-radius:50%;background-color:var(--text-secondary);forced-color-adjust:none;transition:transform var(--duration) var(--ease)}
@media (max-width: 640px){.rs-switch-thumb{top:4px;left:4px;width:36px;height:36px;border-radius:0}}
@media (forced-colors: active){.rs-switch-thumb{background-color:ButtonText}}
@media (prefers-reduced-motion: reduce){.rs-switch-thumb{transition:none}}
.rs-switch-thumb-on{background-color:var(--bg);transform:translateX(14px)}
@media (forced-colors: active){.rs-switch-thumb-on{background-color:HighlightText}}
@media (max-width: 640px){.rs-switch-thumb-on{transform:translateX(20px)}}
